-- Migration 115: Add alt-name matched state/country capitals
-- 92% of state capitals (3,194/3,462) and 84% of country capitals (202/241)
-- matched by primary name in migration 114. The remaining 268 PPLA + 39 PPLC
-- are mostly:
--   - Caribbean islands (AI, AG, BB, BS) - sub-1K pop, not in dr5hn
--   - Obscure African towns (AF, BI, BJ, AO)
--   - Central Asian small towns (AZ)
--
-- This migration adds the alt-name matched ones (where the GeoNames
-- canonical name didn't match but an alt_name did):
--   - 106 additional state capitals
--   - 2 additional country capitals
--
-- Idempotent: sets the same flags.

-- Step 1: Set is_state_capital = 1 for the alt-matched ones
-- (These weren't set by migration 114 because the primary name didn't match)
UPDATE cities
SET is_state_capital = 1
WHERE id IN (8196,66565,8199,64521,8210,153623,31772,102944,31778,102951,47,31792,102984,154205,131167,31843,105060,624,67186,131198,31872,64641,150658,153740,108174,67726,101006,130197,65713,20659,67770,67773,67782,67783,31443,151253,65237,133342,67813,38651,64764,153857,110873,65819,104220,8481,98594,38691,106810,31048,17226,134476,103245,67923,55134,30561,104291,67941,64870,8037,158057,15721,30572,153964,160112,8049,160115,160122,106882,157059,64899,160134,157068,1421,8080,8082,63386,104348,8096,8098,106915,8101,57255,424,8105,130988,8118,107447,8120,8125,64961,63941,67024,102864,102865,8147,8149,8154,21988,8166,8174,8177,8180,66550,8182,8190);

-- Step 2: Set is_country_capital = 1 for alt-matched country capitals
UPDATE cities
SET is_country_capital = 1
WHERE id IN (65737,80394);

-- Step 3: Recompute is_capital = OR of both (only for the cities we just updated)
UPDATE cities
SET is_capital = CASE
  WHEN is_country_capital = 1 OR is_state_capital = 1 THEN 1
  ELSE 0
END
WHERE id IN (8196,66565,8199,64521,8210,153623,31772,102944,31778,102951,47,31792,102984,154205,131167,31843,105060,624,67186,131198,31872,64641,150658,153740,108174,67726,101006,130197,65713,20659,67770,67773,67782,67783,31443,151253,65237,133342,67813,38651,64764,153857,110873,65819,104220,8481,98594,38691,106810,31048,17226,134476,103245,67923,55134,30561,104291,67941,64870,8037,158057,15721,30572,153964,160112,8049,160115,160122,106882,157059,64899,160134,157068,1421,8080,8082,63386,104348,8096,8098,106915,8101,57255,424,8105,130988,8118,107447,8120,8125,64961,63941,67024,102864,102865,8147,8149,8154,21988,8166,8174,8177,8180,66550,8182,8190) OR id IN (65737,80394);

-- Step 4: Recompute capital_type
UPDATE cities
SET capital_type = CASE
  WHEN is_country_capital = 1 AND is_state_capital = 1 THEN 'both'
  WHEN is_country_capital = 1 THEN 'country_capital'
  WHEN is_state_capital = 1 THEN 'state_capital'
  ELSE NULL
END
WHERE id IN (8196,66565,8199,64521,8210,153623,31772,102944,31778,102951,47,31792,102984,154205,131167,31843,105060,624,67186,131198,31872,64641,150658,153740,108174,67726,101006,130197,65713,20659,67770,67773,67782,67783,31443,151253,65237,133342,67813,38651,64764,153857,110873,65819,104220,8481,98594,38691,106810,31048,17226,134476,103245,67923,55134,30561,104291,67941,64870,8037,158057,15721,30572,153964,160112,8049,160115,160122,106882,157059,64899,160134,157068,1421,8080,8082,63386,104348,8096,8098,106915,8101,57255,424,8105,130988,8118,107447,8120,8125,64961,63941,67024,102864,102865,8147,8149,8154,21988,8166,8174,8177,8180,66550,8182,8190) OR id IN (65737,80394);
